import type { Drill, DrillItem, Rng } from "./types.ts";
import type { AnswerSpec, Trap } from "../types.ts";

interface BankEntry {
  prompt: string;
  answer: AnswerSpec;
  solution: string[];
  hint?: string;
  traps?: Trap[];
}

function txt(accept: string[], display?: string): AnswerSpec {
  return { type: "text", accept, display: display ?? accept[0] };
}

function num(value: number, display?: string): AnswerSpec {
  return { type: "number", value, display: display ?? String(value) };
}

function pickBank(rng: Rng, bank: readonly BankEntry[]): DrillItem {
  const e = rng.pick(bank);
  return {
    prompt: e.prompt,
    answer: e.answer,
    solution: e.solution,
    hint: e.hint,
    traps: e.traps,
  };
}

